package broker;

import server.ClientConnection;

import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class Broker {
    private static final Logger logger = Logger.getLogger(Broker.class.getName());
    private final Map<String, Topic> topics = new ConcurrentHashMap<>();

    public Topic subscribe(String topic, ClientConnection connection) {
        Topic t = topics.computeIfAbsent(topic, Topic::new);
        t.addSubscriber(connection);

        return t;
    }

    public void unsubscribe(String topic, ClientConnection connection) {
        topics.computeIfPresent(topic, (_t, topicObj) -> {
            topicObj.removeSubscriber(connection);
            return topicObj.canBeRemoved() ? null : topicObj;
        });
    }

    public void unsubscribeAll(ClientConnection connection) {
        for (String topic : topics.keySet()) {
            unsubscribe(topic, connection);
        }
    }

    public void publish(String topic, byte[] payload) {
        Topic t = topics.get(topic);
        if (t == null) return;

        for (ClientConnection connection : t.getSubscribers()) {
            try {
                connection.sendMessage(topic, payload);
            } catch (IOException e) {
                logger.warning("failed to send notification to client (ID: %s): %s".formatted(connection.getId(), e.getMessage()));
            }
        }
    }

    public String[] listTopics() {
        return topics.keySet().toArray(new String[0]);
    }
}

package broker;

import server.ClientConnection;

import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class Broker {
    private static final Logger logger = Logger.getLogger(Broker.class.getName());
    private final Map<String, Topic> topics = new ConcurrentHashMap<>();

    public Topic subscribe(String topic, ClientConnection connection) {
        Topic t = topics.computeIfAbsent(topic, Topic::new);
        t.addSubscriber(connection);

        return t;
    }

    public void unsubscribe(String topic, ClientConnection connection) {
        topics.computeIfPresent(topic, (_t, topicObj) -> {
            topicObj.removeSubscriber(connection);
            return topicObj.canBeRemoved() ? null : topicObj;
        });
    }

    public void unsubscribeAll(ClientConnection connection) {
        for (String topic : topics.keySet()) {
            unsubscribe(topic, connection);
        }
    }

    public void publish(String topic, byte[] payload, boolean retain) {
        Topic t = topics.get(topic);

        if (retain) {
            if (payload.length == 0) {
                if (t != null) {
                    t.clearRetainedMessage();
                    if (t.canBeRemoved()) {
                        topics.remove(topic, t);
                        t = null;
                    }
                }
            } else {
                t = topics.computeIfAbsent(topic, Topic::new);
                t.setRetainedMessage(payload);
            }
        }

        if (t == null) return;

        for (ClientConnection connection : t.getSubscribers()) {
            try {
                connection.sendMessage(topic, payload);
            } catch (IOException e) {
                logger.warning("failed to send notification to client (ID: %s): %s".formatted(connection.getId(), e.getMessage()));
            }
        }
    }

    public String[] listTopics() {
        return topics.keySet().toArray(new String[0]);
    }
}

package server;

import broker.Broker;
import command.*;
import services.analytics.AnalyticsService;

import java.nio.file.Path;

public class ServerBootstrap {
    private static final Path DEFAULT_DIR = Path.of("data");
    public static final Path DEFAULT_TOPIC_DATA_FILE_PATH = DEFAULT_DIR.resolve("topic_data.json");

    public static CommandRegistry buildRegistry(Broker broker, AnalyticsService analyticsService) {
        CommandRegistry registry = new CommandRegistry();

        // Register commands here
        registry.register(CommandCode.SUBSCRIBE, new SubscribeCommand(broker, analyticsService));
        registry.register(CommandCode.UNSUBSCRIBE, new UnsubscribeCommand(broker, analyticsService));
        registry.register(CommandCode.PUBLISH, new PublishCommand(broker, analyticsService));
        registry.register(CommandCode.LIST, new ListCommand(broker));
        registry.register(CommandCode.ANALYTICS, new AnalyticsCommand(analyticsService));

        return registry;
    }
}

