package e2e;

import command.CommandCode;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import protocol.Frame;
import protocol.FrameReader;
import protocol.FrameWriter;
import protocol.MessageCode;
import protocol.ProtocolException;
import server.Server;

import java.io.*;
import java.net.InetAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ServerE2ETest {

    private static final String HOST = "127.0.0.1";
    private static final List<Path> PERSISTED_DATA_FILES = List.of(
            Path.of("data", "topic_data.json"),
            Path.of("data", "client_sessions.json")
    );

    private final Map<Path, byte[]> backup = new HashMap<>();
    private final Set<Path> originallyMissing = new HashSet<>();

    private Server server;
    private Thread serverThread;
    private int port;

    @BeforeEach
    void setUp() throws Exception {
        backupAndResetDataFiles();

        port = findFreePort();
        server = new Server(HOST, port);
        serverThread = Thread.startVirtualThread(server::start);

        waitForServerReady();
    }

    @AfterEach
    void tearDown() throws Exception {
        if (server != null) {
            server.close();
        }

        if (serverThread != null) {
            serverThread.join(1500);
        }

        restoreDataFiles();
    }

    @Test
    void publishAfterSubscribeDeliversNotificationToSubscriber() throws Exception {
        UUID subscriberId = UUID.randomUUID();
        UUID publisherId = UUID.randomUUID();
        String topic = "e2e/weather/" + UUID.randomUUID();
        byte[] payload = "sunny".getBytes(StandardCharsets.UTF_8);

        try (ClientSession subscriber = connectClient(subscriberId, false);
             ClientSession publisher = connectClient(publisherId, false)) {

            sendSubscribe(subscriber.out(), topic);
            Frame subscribeAck = readFrame(subscriber.in());
            assertEquals(MessageCode.ACK.code, subscribeAck.type());

            sendPublish(publisher.out(), topic, false, payload);
            Frame publishAck = readFrame(publisher.in());
            assertEquals(MessageCode.ACK.code, publishAck.type());

            Frame notification = readFrame(subscriber.in());
            assertEquals(MessageCode.NOTIFICATION.code, notification.type());

            DataInputStream payloadIn = new DataInputStream(new ByteArrayInputStream(notification.payload()));
            String deliveredTopic = payloadIn.readUTF();
            byte[] deliveredPayload = payloadIn.readAllBytes();

            assertEquals(topic, deliveredTopic);
            assertArrayEquals(payload, deliveredPayload);
        }
    }

    @Test
    void retainedMessageIsReturnedInSubscribeAck() throws Exception {
        UUID publisherId = UUID.randomUUID();
        UUID subscriberId = UUID.randomUUID();
        String topic = "e2e/retain/" + UUID.randomUUID();
        byte[] retained = "retained-message".getBytes(StandardCharsets.UTF_8);

        try (ClientSession publisher = connectClient(publisherId, false)) {
            sendPublish(publisher.out(), topic, true, retained);
            Frame publishAck = readFrame(publisher.in());
            assertEquals(MessageCode.ACK.code, publishAck.type());
        }

        try (ClientSession subscriber = connectClient(subscriberId, false)) {
            sendSubscribe(subscriber.out(), topic);
            Frame subscribeAck = readFrame(subscriber.in());

            assertEquals(MessageCode.ACK.code, subscribeAck.type());
            assertArrayEquals(retained, subscribeAck.payload());
        }
    }

    private ClientSession connectClient(UUID clientId, boolean clearSessionIfExists) throws IOException {
        Socket socket = new Socket(HOST, port);
        socket.setSoTimeout(3000);

        DataInputStream in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
        DataOutputStream out = new DataOutputStream(socket.getOutputStream());

        ByteArrayOutputStream authPayloadBuffer = new ByteArrayOutputStream();
        DataOutputStream authPayloadOut = new DataOutputStream(authPayloadBuffer);
        authPayloadOut.writeUTF(clientId.toString());
        authPayloadOut.writeBoolean(clearSessionIfExists);

        FrameWriter.writeFrame(out, MessageCode.AUTHENTICATE.code, UUID.randomUUID(), authPayloadBuffer.toByteArray());

        return new ClientSession(socket, in, out);
    }

    private static void sendSubscribe(DataOutputStream out, String topic) throws IOException {
        sendCommand(out, CommandCode.SUBSCRIBE.code, topic.getBytes(StandardCharsets.UTF_8));
    }

    private static void sendPublish(DataOutputStream out, String topic, boolean retain, byte[] payload) throws IOException {
        ByteArrayOutputStream commandPayloadBuffer = new ByteArrayOutputStream();
        DataOutputStream commandPayloadOut = new DataOutputStream(commandPayloadBuffer);
        commandPayloadOut.writeUTF(topic);
        commandPayloadOut.writeBoolean(retain);
        commandPayloadOut.write(payload);

        sendCommand(out, CommandCode.PUBLISH.code, commandPayloadBuffer.toByteArray());
    }

    private static void sendCommand(DataOutputStream out, byte commandCode, byte[] commandPayload) throws IOException {
        ByteArrayOutputStream framePayloadBuffer = new ByteArrayOutputStream();
        framePayloadBuffer.write(commandCode);
        framePayloadBuffer.write(commandPayload);

        FrameWriter.writeFrame(out, MessageCode.COMMAND.code, UUID.randomUUID(), framePayloadBuffer.toByteArray());
    }

    private static Frame readFrame(DataInputStream in) throws IOException, ProtocolException {
        return FrameReader.readFrame(in);
    }

    private void waitForServerReady() throws Exception {
        long deadline = System.currentTimeMillis() + 3000;

        while (System.currentTimeMillis() < deadline) {
            try (Socket probe = new Socket(HOST, port)) {
                DataOutputStream out = new DataOutputStream(probe.getOutputStream());
                ByteArrayOutputStream authPayloadBuffer = new ByteArrayOutputStream();
                DataOutputStream authPayloadOut = new DataOutputStream(authPayloadBuffer);
                authPayloadOut.writeUTF(UUID.randomUUID().toString());
                authPayloadOut.writeBoolean(false);
                FrameWriter.writeFrame(out, MessageCode.AUTHENTICATE.code, UUID.randomUUID(), authPayloadBuffer.toByteArray());
                return;
            } catch (IOException ignored) {
                Thread.sleep(25);
            }
        }

        assertTrue(false, "Server did not become ready in time");
    }

    private static int findFreePort() throws IOException {
        try (ServerSocket socket = new ServerSocket(0, 50, InetAddress.getByName(HOST))) {
            return socket.getLocalPort();
        }
    }

    private void backupAndResetDataFiles() throws IOException {
        for (Path file : PERSISTED_DATA_FILES) {
            Path absolute = file.toAbsolutePath();
            Path parent = absolute.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }

            if (Files.exists(absolute)) {
                backup.put(absolute, Files.readAllBytes(absolute));
                Files.delete(absolute);
            } else {
                originallyMissing.add(absolute);
            }
        }
    }

    private void restoreDataFiles() throws IOException {
        for (Path file : PERSISTED_DATA_FILES) {
            Path absolute = file.toAbsolutePath();
            byte[] previous = backup.get(absolute);

            if (previous != null) {
                Files.write(absolute, previous);
            } else if (originallyMissing.contains(absolute) && Files.exists(absolute)) {
                Files.delete(absolute);
            }
        }
    }

    private record ClientSession(Socket socket, DataInputStream in, DataOutputStream out) implements AutoCloseable {
        @Override
        public void close() throws IOException {
            socket.close();
        }
    }
}

package protocol;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class FrameReaderWriterTest {

    @Test
    void roundTripFramePreservesTypeIdAndPayload() throws IOException, ProtocolException {
        UUID id = UUID.randomUUID();
        byte[] payload = new byte[]{1, 2, 3, 4, 5};

        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream dataOutput = new DataOutputStream(output);
        FrameWriter.writeFrame(dataOutput, MessageCode.COMMAND.code, id, payload);

        DataInputStream dataInput = new DataInputStream(new ByteArrayInputStream(output.toByteArray()));
        Frame frame = FrameReader.readFrame(dataInput);

        assertEquals(MessageCode.COMMAND.code, frame.type());
        assertEquals(id, frame.id());
        assertArrayEquals(payload, frame.payload());
    }

    @Test
    void writeFrameWithNullPayloadRoundTripsAsEmptyPayload() throws IOException, ProtocolException {
        UUID id = UUID.randomUUID();

        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream dataOutput = new DataOutputStream(output);
        FrameWriter.writeFrame(dataOutput, MessageCode.ACK.code, id, null);

        DataInputStream dataInput = new DataInputStream(new ByteArrayInputStream(output.toByteArray()));
        Frame frame = FrameReader.readFrame(dataInput);

        assertEquals(MessageCode.ACK.code, frame.type());
        assertEquals(id, frame.id());
        assertArrayEquals(new byte[0], frame.payload());
    }

    @Test
    void readFrameRejectsNegativePayloadLength() throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream dataOutput = new DataOutputStream(output);
        writeHeader(dataOutput, MessageCode.COMMAND.code, UUID.randomUUID());
        dataOutput.writeInt(-1);

        DataInputStream dataInput = new DataInputStream(new ByteArrayInputStream(output.toByteArray()));

        ProtocolException exception = assertThrows(ProtocolException.class, () -> FrameReader.readFrame(dataInput));
        assertEquals("Invalid payload length: -1", exception.getMessage());
    }

    @Test
    void readFrameRejectsPayloadLargerThanMaxAllowed() throws IOException {
        int maxPayloadSize = 10 * 1024 * 1024;
        int oversizedLength = maxPayloadSize + 1;

        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream dataOutput = new DataOutputStream(output);
        writeHeader(dataOutput, MessageCode.COMMAND.code, UUID.randomUUID());
        dataOutput.writeInt(oversizedLength);

        DataInputStream dataInput = new DataInputStream(new ByteArrayInputStream(output.toByteArray()));

        ProtocolException exception = assertThrows(ProtocolException.class, () -> FrameReader.readFrame(dataInput));
        assertEquals("Invalid payload length: " + oversizedLength, exception.getMessage());
    }

    @Test
    void readFrameThrowsWhenPayloadIsTruncated() throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream dataOutput = new DataOutputStream(output);
        writeHeader(dataOutput, MessageCode.COMMAND.code, UUID.randomUUID());
        dataOutput.writeInt(4);
        dataOutput.write(new byte[]{9, 8});

        DataInputStream dataInput = new DataInputStream(new ByteArrayInputStream(output.toByteArray()));

        assertThrows(EOFException.class, () -> FrameReader.readFrame(dataInput));
    }

    private static void writeHeader(DataOutputStream out, byte type, UUID id) throws IOException {
        out.writeByte(type);
        out.writeLong(id.getMostSignificantBits());
        out.writeLong(id.getLeastSignificantBits());
    }
}

package server;

import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class ClientSessionDataTest {

    @Test
    void constructorUsesSafeDefaultsWhenInputsAreNull() {
        ClientSessionData data = new ClientSessionData(UUID.randomUUID(), null, null);

        assertEquals(0, data.subscribedTopics().length);
        assertEquals(0, data.undeliveredMessages().size());
    }

    @Test
    void constructorDefensivelyCopiesSubscribedTopics() {
        String[] topics = new String[]{"weather"};

        ClientSessionData data = new ClientSessionData(UUID.randomUUID(), topics, Map.of());
        topics[0] = "news";

        assertArrayEquals(new String[]{"weather"}, data.subscribedTopics());
    }

    @Test
    void constructorCreatesUnmodifiableUndeliveredMessagesMap() {
        Map<String, byte[][]> messages = new HashMap<>();
        messages.put("weather", new byte[][]{{1}});

        ClientSessionData data = new ClientSessionData(UUID.randomUUID(), new String[0], messages);

        assertThrows(UnsupportedOperationException.class, () -> data.undeliveredMessages().put("news", new byte[][]{{2}}));
    }
}

package server;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.file.Path;
import java.util.Arrays;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ClientSessionHandlerTest {

    @TempDir
    Path tempDir;

    @Test
    void getOrCreateAndClosePersistsSessionData() {
        Path file = tempDir.resolve("client_sessions.json");
        UUID clientId = UUID.randomUUID();

        ClientSessionHandler writer = new ClientSessionHandler(file);
        ClientSession session = writer.getOrCreate(clientId);
        session.subscribeTopic("weather");
        session.enqueueUndeliveredMessage("weather", "queued".getBytes());
        writer.close();

        ClientSessionHandler reader = new ClientSessionHandler(file);
        try {
            ClientSession loadedSession = reader.get(clientId.toString());
            assertNotNull(loadedSession);

            ClientSessionData data = loadedSession.toData();
            assertTrue(Arrays.asList(data.subscribedTopics()).contains("weather"));
            assertArrayEquals("queued".getBytes(), data.undeliveredMessages().get("weather")[0]);
        } finally {
            reader.close();
        }
    }

    @Test
    void removeDeletesSessionFromInMemoryState() {
        Path file = tempDir.resolve("client_sessions.json");
        UUID clientId = UUID.randomUUID();

        ClientSessionHandler handler = new ClientSessionHandler(file);
        try {
            handler.getOrCreate(clientId);
            handler.remove(clientId.toString());

            assertTrue(handler.get(clientId.toString()) == null);
        } finally {
            handler.close();
        }
    }
}

package server;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

class ClientSessionTest {

    @Test
    void subscribeAndUnsubscribeTopicUpdateSessionState() {
        AtomicInteger dirtyCounter = new AtomicInteger();
        ClientSession session = new ClientSession(UUID.randomUUID(), dirtyCounter::incrementAndGet);

        session.subscribeTopic("weather");
        session.unsubscribeTopic("weather");

        ClientSessionData data = session.toData();
        assertEquals(0, data.subscribedTopics().length);
        assertEquals(2, dirtyCounter.get());
    }

    @Test
    void enqueueUndeliveredMessageStoresDefensiveCopy() {
        ClientSession session = new ClientSession(UUID.randomUUID(), null);
        byte[] payload = new byte[]{1, 2, 3};

        session.enqueueUndeliveredMessage("weather", payload);
        payload[0] = 9;

        byte[] persisted = session.toData().undeliveredMessages().get("weather")[0];
        assertArrayEquals(new byte[]{1, 2, 3}, persisted);
    }

    @Test
    void flushUndeliveredMessagesSendsAndClearsQueue() throws IOException {
        ClientSession session = new ClientSession(UUID.randomUUID(), null);
        ClientConnection connection = mock(ClientConnection.class);

        session.enqueueUndeliveredMessage("weather", "sunny".getBytes());
        session.enqueueUndeliveredMessage("weather", "rainy".getBytes());
        session.setClientConnection(connection);

        session.flushUndeliveredMessages();

        verify(connection, times(2)).sendMessage(org.mockito.ArgumentMatchers.eq("weather"), org.mockito.ArgumentMatchers.any(byte[].class));
        assertFalse(session.toData().undeliveredMessages().containsKey("weather"));
    }

    @Test
    void flushUndeliveredMessagesWithoutConnectionKeepsQueue() throws IOException {
        ClientSession session = new ClientSession(UUID.randomUUID(), null);
        session.enqueueUndeliveredMessage("weather", "offline".getBytes());

        session.flushUndeliveredMessages();

        Map<String, byte[][]> undelivered = session.toData().undeliveredMessages();
        assertTrue(undelivered.containsKey("weather"));
        assertEquals(1, undelivered.get("weather").length);
    }

    @Test
    void clearSessionDataRemovesTopicsAndQueuedMessages() {
        ClientSession session = new ClientSession(UUID.randomUUID(), null);
        session.subscribeTopic("weather");
        session.enqueueUndeliveredMessage("weather", "queued".getBytes());

        session.clearSessionData();

        ClientSessionData data = session.toData();
        assertEquals(0, data.subscribedTopics().length);
        assertEquals(0, data.undeliveredMessages().size());
    }
}

package server;

import broker.Broker;
import broker.store.TopicDataStore;
import command.*;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import services.analytics.AnalyticsService;

import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertInstanceOf;

class ServerBootstrapTest {

    @TempDir
    Path tempDir;

    private TopicDataStore topicDataStore;
    private ClientSessionHandler clientSessionHandler;
    private Broker broker;

    @BeforeEach
    void setUp() {
        topicDataStore = new TopicDataStore(tempDir.resolve("topic_data.json"));
        clientSessionHandler = new ClientSessionHandler(tempDir.resolve("client_sessions.json"));
        broker = new Broker(topicDataStore, new AnalyticsService(), clientSessionHandler);
    }

    @AfterEach
    void tearDown() {
        broker.shutdown();
        clientSessionHandler.close();
    }

    @Test
    void buildRegistryRegistersAllExpectedCommandHandlers() {
        AnalyticsService analyticsService = new AnalyticsService();
        CommandRegistry registry = ServerBootstrap.buildRegistry(broker, analyticsService);

        assertInstanceOf(SubscribeCommand.class, registry.get(CommandCode.SUBSCRIBE));
        assertInstanceOf(UnsubscribeCommand.class, registry.get(CommandCode.UNSUBSCRIBE));
        assertInstanceOf(PublishCommand.class, registry.get(CommandCode.PUBLISH));
        assertInstanceOf(ListCommand.class, registry.get(CommandCode.LIST));
        assertInstanceOf(AnalyticsCommand.class, registry.get(CommandCode.ANALYTICS));
    }
}
